import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// 🔑 API ANAHTARLARI
const GEMINI_API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 
const WEATHER_API_KEY = "https://api.openweathermap.org/data/2.5/weather?lat={lat}&lon={lon}&appid={API key}"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  // 1. Backend'den Verileri Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("Backend hatası:", err));
  }, []);

  // 2. Akıllı Bilgi ve Hava Durumu Servisi
  const askSmartAI = async (mekan) => {
    // Zaten açıksa kapat
    if (seciliMekanId === mekan.id) {
      setSeciliMekanId(null);
      return;
    }

    setSeciliMekanId(mekan.id);
    setLoading(true);
    setAiBilgi({ cevap: "", temp: "", durum: "" });

    try {
      // Önce Hava Durumunu Al
      const weatherUrl = `https://api.openweathermap.org/data/2.5/weather?lat=${mekan.lat}&lon=${mekan.lon}&units=metric&lang=tr&appid=${WEATHER_API_KEY}`;
      const wRes = await fetch(weatherUrl);

      if (!wRes.ok) throw new Error("Hava durumu anahtarı henüz aktif değil.");

      const wData = await wRes.json();
      const sicaklik = Math.round(wData.main.temp);
      const havaDurumu = wData.weather[0].description;

      // Sonra Gemini'ye Sor
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });

      const prompt = `Antalya ${mekan.ad} için hava şu an ${sicaklik} derece ve ${havaDurumu}. 
      Bu mekana gidecek birine hava durumunu da dikkate alarak 2 cümlelik samimi bir tavsiye ver.`;

      const result = await model.generateContent(prompt);
      const text = result.response.text();

      setAiBilgi({ cevap: text, temp: sicaklik, durum: havaDurumu });

    } catch (error) {
      console.error("Hata:", error);
      setAiBilgi({ 
        cevap: "Hava durumu API'si şu an yanıt vermiyor (Aktivasyon 1-2 saat sürebilir). Yine de burası harika bir tercih!", 
        temp: "--", 
        durum: "Veri Yok" 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ background: '#f8fafc', minHeight: '100vh', fontFamily: 'Poppins, sans-serif', padding: '20px' }}>
      <style>{`
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 25px; max-width: 1200px; margin: 0 auto; }
        .card { background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.06); display: flex; flex-direction: column; transition: 0.3s; border: 1px solid #e2e8f0; }
        .card:hover { transform: translateY(-5px); border-color: #0e7490; }
        .ai-inline-panel { 
          background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%); 
          padding: 20px; border-top: 2px solid #0e7490; 
          animation: slideDown 0.3s ease-out;
        }
        @keyframes slideDown { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }
        .btn-ai { background: #0e7490; color: white; border: none; padding: 12px; border-radius: 10px; cursor: pointer; font-weight: 600; width: 100%; transition: 0.2s; }
        .btn-ai:hover { background: #155e75; }
      `}</style>

      <h1 style={{ textAlign: 'center', color: '#0e7490', marginBottom: '40px' }}>🧭 ROTA ASİSTANI</h1>

      <div className="grid">
        {mekanlar.map(mekan => (
          <div key={mekan.id} className="card">
            <img src={mekan.resim} style={{ width: '100%', height: '220px', objectFit: 'cover' }} alt={mekan.ad} />
            <div style={{ padding: '20px' }}>
              <h3 style={{ margin: '0 0 10px 0', fontSize: '18px' }}>{mekan.ad}</h3>
              <p style={{ fontSize: '13px', color: '#64748b', lineHeight: '1.6', marginBottom: '15px' }}>{mekan.aciklama}</p>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <span style={{ fontSize: '13px', fontWeight: '700' }}>📍 {mekan.bolge}</span>
                <span style={{ color: '#0e7490', fontWeight: '800' }}>{mekan.ucret === 0 ? 'Ücretsiz' : `${mekan.ucret} ₺`}</span>
              </div>
              <button className="btn-ai" onClick={() => askSmartAI(mekan)}>
                {seciliMekanId === mekan.id && loading ? "⌛ Analiz Ediliyor..." : "✨ Akıllı Bilgi Al"}
              </button>
            </div>

            {/* KARTIN ALTINA AÇILAN PANEL */}
            {seciliMekanId === mekan.id && (
              <div className="ai-inline-panel">
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '10px' }}>
                  <span style={{ fontSize: '24px' }}>🌤️</span>
                  <div>
                    <div style={{ fontWeight: 800, color: '#0369a1', fontSize: '14px' }}>
                      {loading ? "Bağlanıyor..." : `${aiBilgi.temp}°C - ${aiBilgi.durum.toUpperCase()}`}
                    </div>
                  </div>
                </div>
                <p style={{ fontSize: '13px', color: '#0c4a6e', margin: 0, fontStyle: 'italic', lineHeight: '1.5' }}>
                  {loading ? "Yapay zeka tavsiye oluşturuyor..." : `"${aiBilgi.cevap}"`}
                </p>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
